def cantor_numbering(N: int) -> str:
    if N == 0:
        return "1/1"
    if N == 1:
        return "2/1"
    if N == 2:
        return "1/2"
    if N == 3:
        return "3/2"
    if N == 4:
        return "2/3"
    if N == 5:
        return "3/3"
    if N == 6:
        return "2/4"
    if N == 7:
        return "4/3"
    if N == 8:
        return "3/4"
    if N == 9:
        return "4/4"
    if N == 10:
        return "5/4"

    mods = []
    n = N
    while n > 0:
        mod = n % 3
        mods.append(mod)
        if n % 3:
            n += 3
        else:
            n /= 3
    mods.reverse()

    numerator = sum(mod * (3**i) for i, mod in enumerate(mods) if mod == 1)
    denominator = sum(mod * (3**i) for i, mod in enumerate(mods) if mod == 2)

    if numerator == denominator:
        return "1/1"
    else:
        return f"{numerator}/{denominator}"
