def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue  # Skip terms with zero coefficients
        degree = n - i - 1  # Calculate the degree based on index
        if degree == 0:  # Constant term
            result.append(str(coeff))
        else:
            variant = '' if abs(coeff) == 1 else f'{coeff}'
            if degree > 1:
                variant += f'x^{degree}'
            elif degree == 1:
                variant += f'x'
            result.append(f'{variant}')
            if i > 0:  # Add '+' for terms other than the first
                result.append('+')
    return ''.join(result)
