def decode(encoded: str, original: str, message: str) -> str:
    # Create a dictionary mapping original letters to encoded letters
    mapping = {}

    # Initial check to ensure both original and encoded strings are of equal length
    if len(original) != len(encoded):
        return "Failed"

    # Formulate the mapping and check for contradictions
    for i in range(len(encoded)):
        if encoded[i] in mapping and mapping[encoded[i]] != original[i]:
            return "Failed"
        mapping[encoded[i]] = original[i]

    # If no contradictions and all elements are mapped, decode the message
    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)
