def count_sequences(n: int, last: int, memo: dict) -> int:
    if (n, last) in memo:
        return memo[(n, last)]

    if last < 1:
        return 0

    if last == 1 and n == last:
        memo[(n, last)] = 1
        return 1

    valid_sequences = count_sequences(n, last // 2, memo) + count_sequences(n, last - 1, memo)
    memo[(n, last)] = valid_sequences
    return valid_sequences
