def find_most_unhappy_day(schedule: List[Tuple[int, int]]) -> int:
    total_hours = sum(hours for hours, _ in schedule)
    if total_hours <= 8:
        return 0

    max_unhappiness = total_hours - 8
    unhappiness_days = []

    for day, (school_hours, extra_hours) in enumerate(schedule, start=1):
        hours_spent = school_hours + extra_hours
        if hours_spent > 8:
            happiness_loss = hours_spent - 8
            if happiness_loss > max_unhappiness:
                max_unhappiness = happiness_loss
                unhappiness_days = [day]
            elif happiness_loss == max_unhappiness:
                unhappiness_days.append(day)

    return min(unhappiness_days) if unhappiness_days else 0
